// AI-generated fictional portrait for the demo persona only.
export const demoPhoto =
  'data:image/jpeg;base64,';

export function applyDemoPhotoToState(candidate) {
  let changed = false;
  for (const lang of ['zh', 'en']) {
    const basics = candidate?.profiles?.[lang]?.basics;
    const name = lang === 'zh' ? '林小溪' : 'XIAOXI LIN';
    if (!basics || basics.email !== 'demo@example.com' || basics.name !== name || basics.photo)
      continue;
    basics.photo = demoPhoto;
    basics.photoOriginal = demoPhoto;
    basics.photoPosition = 'center';
    changed = true;
  }
  return changed;
}
